//! JPEG frame thumbnails, generated by ffmpeg and persisted in SQLite.
//!
//! The webview cannot screenshot scanned library items: their `asset://`
//! source has no CORS header, so `crossOrigin` loads fail and relaxed loads
//! taint the canvas, making `toDataURL` throw. Frames are therefore captured
//! here — one synchronous ffmpeg run per thumbnail, run from the IPC
//! command thread pool — and stored as blobs in the `thumbnails` table
//! (`db::init_schema`), keyed by the media item's absolute file path.
//!
//! `thumb_generate` is the whole pipeline in a single IPC roundtrip: capture,
//! persist, return. `thumb_get` reads an existing blob. Both return `None`
//! (not `Err`) when no thumbnail can be produced — missing ffmpeg, unknown
//! container, corrupt media — so the front-end falls back to its webview
//! capture pipeline for whatever the desktop path cannot serve.

use std::io::Read;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use rusqlite::{params, Connection, OptionalExtension};
use tauri::State;

use crate::db::Database;

/// ffmpeg lives in PATH for the shipped desktop targets; a fixed absolute
/// path keeps the command inventory explicit. Shared with `waveform.rs`,
/// which decodes audio through the same binary.
pub(crate) const FFMPEG_PATH: &str = "/usr/bin/ffmpeg";

/// Video containers accepted for frame extraction (lowercase, no dot).
const VIDEO_EXTENSIONS: &[&str] = &[
    "mp4", "m4v", "mkv", "webm", "mov", "avi", "ogv", "ts", "m2ts", "mpg", "mpeg", "wmv", "flv",
    "3gp",
];

/// Seek clamp for frame extraction: start just after the first frame, never
/// more than 45 seconds in.
const SEEK_MIN_SECONDS: f64 = 0.05;
const SEEK_MAX_SECONDS: f64 = 45.0;

/// Hard cap for one JPEG (sane images for 240px frames are tens of KB).
const MAX_OUTPUT_BYTES: usize = 2_000_000;

/// Kill long-running extractions instead of blocking a command thread.
const FFMPEG_TIMEOUT: Duration = Duration::from_secs(10);
/// Poll granularity for the timeout watch.
const FFMPEG_POLL: Duration = Duration::from_millis(40);

/// Steal the file extension of `path` (lowercased, whenever present).
fn extension_of(path: &Path) -> String {
    path.extension()
        .map(|e| e.to_string_lossy().to_lowercase())
        .unwrap_or_default()
}

/// True when `path` points at a container ffmpeg can extract frames from.
pub(crate) fn is_video_path(path: &Path) -> bool {
    let extension = extension_of(path);
    !extension.is_empty() && VIDEO_EXTENSIONS.contains(&extension.as_str())
}

/// Clamp an extraction seek into the bounds ffmpeg was validated against.
pub(crate) fn clamp_seek(seconds: f64) -> f64 {
    if !seconds.is_finite() {
        return SEEK_MIN_SECONDS;
    }
    seconds.clamp(SEEK_MIN_SECONDS, SEEK_MAX_SECONDS)
}

/// Store (or overwrite) the thumbnail bytes for `path`.
fn store_thumbnail(
    conn: &Connection,
    path: &str,
    data: &[u8],
    now_ms: i64,
) -> rusqlite::Result<usize> {
    conn.execute(
        "INSERT INTO thumbnails (path, data, updated_at)
         VALUES (?1, ?2, ?3)
         ON CONFLICT(path) DO UPDATE SET
             data = excluded.data,
             updated_at = excluded.updated_at",
        params![path, data, now_ms],
    )
}

/// Read the thumbnail bytes stored for `path`, if any.
fn load_thumbnail(conn: &Connection, path: &str) -> rusqlite::Result<Option<Vec<u8>>> {
    conn.query_row(
        "SELECT data FROM thumbnails WHERE path = ?1",
        params![path],
        |row| row.get(0),
    )
    .optional()
}

fn unix_time_ms() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as i64
}

/// Run the extraction command, guarding against hangs and oversized output.
///
/// ffmpeg writes the (single) JPEG frame to stdout while a reader thread
/// drains the pipe into a capped buffer — draining is what keeps the child
/// from deadlocking on a full pipe. The command thread watches with
/// `try_wait` so it can kill anything that overstays `FFMPEG_TIMEOUT`,
/// whether it hung, stalled against the output cap, or crashed mid-write.
fn run_ffmpeg_frame(ffmpeg: &str, path: &str, seek: f64) -> Option<Vec<u8>> {
    let started = SystemTime::now();
    let seek_arg = seek.to_string();

    let mut child = Command::new(ffmpeg)
        .args([
            "-hide_banner",
            "-loglevel",
            "error",
            "-ss",
            seek_arg.as_str(),
            "-i",
            path,
            "-frames:v",
            "1",
            "-vf",
            "scale=-2:240",
            "-q:v",
            "5",
            "-f",
            "image2",
            "-",
        ])
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .ok()?;

    // Reader thread: report the copied length through an atomic so the watch
    // loop can see the cap being exceeded without consuming the buffer.
    let stdout = child.stdout.take()?;
    let copied = Arc::new(AtomicUsize::new(0));
    let reader = spawn_stdout_reader(stdout, Arc::clone(&copied));

    loop {
        match child.try_wait() {
            Ok(Some(status)) => {
                let bytes = reader.join().unwrap_or_default();
                if !status.success() || bytes.is_empty() || bytes.len() >= MAX_OUTPUT_BYTES {
                    return None;
                }
                return Some(bytes);
            }
            Ok(None) => {
                if copied.load(Ordering::Relaxed) >= MAX_OUTPUT_BYTES {
                    let _ = child.kill();
                    let _ = child.wait();
                    return None;
                }
                if started.elapsed().unwrap_or_default() >= FFMPEG_TIMEOUT {
                    let _ = child.kill();
                    let _ = child.wait();
                    // The pipe is closed by the kill; the reader exits on its
                    // own and its (abandoned) output is never consumed.
                    return None;
                }
                std::thread::sleep(FFMPEG_POLL);
            }
            Err(_) => {
                let _ = child.kill();
                let _ = child.wait();
                return None;
            }
        }
    }
}

/// Drain `stdout` into a `MAX_OUTPUT_BYTES`-capped buffer on a worker thread.
/// Shared with `waveform.rs`, which caps its own decode output the same way.
pub(crate) fn spawn_stdout_reader(
    mut stdout: impl Read + Send + 'static,
    copied: Arc<AtomicUsize>,
) -> std::thread::JoinHandle<Vec<u8>> {
    std::thread::spawn(move || {
        let mut buffer = Vec::new();
        let mut chunk = [0u8; 8192];
        loop {
            match stdout.read(&mut chunk) {
                Ok(0) => break,
                Ok(n) => {
                    buffer.extend_from_slice(&chunk[..n]);
                    copied.store(buffer.len(), Ordering::Relaxed);
                    if buffer.len() >= MAX_OUTPUT_BYTES {
                        break;
                    }
                }
                Err(_) => break,
            }
        }
        buffer
    })
}

/// Read a previously persisted thumbnail, `None` when one was never stored.
#[tauri::command(async)]
pub fn thumb_get(state: State<'_, Database>, path: String) -> Result<Option<Vec<u8>>, String> {
    let conn = state.0.lock().map_err(|_| "database is locked".to_string())?;
    load_thumbnail(&conn, &path).map_err(|e| e.to_string())
}

/// Extract one frame with ffmpeg and persist it, in a single IPC roundtrip.
///
/// Returns the JPEG bytes, or `None` when no frame could be produced
/// (non-absolute path, non-video container, missing file, missing ffmpeg
/// binary, failed extraction) — the front-end then falls back to its own
/// webview capture.
#[tauri::command(async)]
pub fn thumb_generate(
    state: State<'_, Database>,
    path: String,
    seek_seconds: f64,
) -> Result<Option<Vec<u8>>, String> {
    let file_path = PathBuf::from(&path);
    if !file_path.is_absolute() || !is_video_path(&file_path) {
        return Ok(None);
    }
    if !file_path.is_file() {
        return Ok(None);
    }
    if !Path::new(FFMPEG_PATH).is_file() {
        // Missing binary: let the webview capture take over.
        return Ok(None);
    }

    let bytes = run_ffmpeg_frame(FFMPEG_PATH, &path, clamp_seek(seek_seconds));

    if let Some(data) = bytes {
        let conn = state.0.lock().map_err(|_| "database is locked".to_string())?;
        store_thumbnail(&conn, &path, &data, unix_time_ms()).map_err(|e| e.to_string())?;
        Ok(Some(data))
    } else {
        Ok(None)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::db::init_schema;

    fn test_conn() -> Connection {
        let conn = Connection::open_in_memory().unwrap();
        init_schema(&conn).unwrap();
        conn
    }

    #[test]
    fn test_thumbnail_roundtrip_and_overwrite() {
        let conn = test_conn();
        assert_eq!(load_thumbnail(&conn, "/videos/a.mkv").unwrap(), None);

        store_thumbnail(&conn, "/videos/a.mkv", b"first", 1_000).unwrap();
        assert_eq!(
            load_thumbnail(&conn, "/videos/a.mkv").unwrap(),
            Some(b"first".to_vec())
        );

        // Storing again replaces the blob without adding a second row.
        store_thumbnail(&conn, "/videos/a.mkv", b"second", 2_000).unwrap();
        assert_eq!(
            load_thumbnail(&conn, "/videos/a.mkv").unwrap(),
            Some(b"second".to_vec())
        );

        let count: i64 = conn
            .query_row("SELECT COUNT(*) FROM thumbnails", [], |row| row.get(0))
            .unwrap();
        assert_eq!(count, 1);

        // Other paths stay untouched and independently keyed.
        store_thumbnail(&conn, "/videos/b.mp4", b"other", 3_000).unwrap();
        assert_eq!(
            load_thumbnail(&conn, "/videos/b.mp4").unwrap(),
            Some(b"other".to_vec())
        );
        assert_eq!(
            load_thumbnail(&conn, "/videos/a.mkv").unwrap(),
            Some(b"second".to_vec())
        );
    }

    #[test]
    fn test_thumbnail_keys_are_independent() {
        let conn = test_conn();
        store_thumbnail(&conn, "/videos/a.mkv", b"one", 1).unwrap();
        store_thumbnail(&conn, "/videos/b.mkv", b"two", 2).unwrap();
        assert_eq!(load_thumbnail(&conn, "/videos/a.mkv").unwrap(), Some(b"one".to_vec()));
        assert_eq!(load_thumbnail(&conn, "/videos/b.mkv").unwrap(), Some(b"two".to_vec()));
        assert_eq!(
            load_thumbnail(&conn, "/videos/missing.mkv").unwrap(),
            None,
            "unknown path resolves to None, not an error"
        );
    }

    #[test]
    fn test_is_video_path() {
        assert!(is_video_path(Path::new("/home/u/Videos/Clip.MP4")));
        assert!(is_video_path(Path::new("/home/u/Videos/Pokèmon.mkv")));
        assert!(is_video_path(Path::new("/u/v/mpeg/clip.mpeg")));
        assert!(is_video_path(Path::new("/u/v/mpeg/clip.mpg")));
        assert!(is_video_path(Path::new("/u/v/mpeg/clip.TS")));
        assert!(!is_video_path(Path::new("/u/v/not/audio.mp3")));
        assert!(!is_video_path(Path::new("/u/v/not/image.jpg")));
        assert!(!is_video_path(Path::new("/u/v/no/extension")));
        assert!(!is_video_path(Path::new("")));
        // Extension-only dot files are not video paths either.
        assert!(!is_video_path(Path::new("/u/v/hidden/.mp4")));
    }

    #[test]
    fn test_clamp_seek_bounds() {
        assert_eq!(clamp_seek(-5.0), SEEK_MIN_SECONDS);
        assert_eq!(clamp_seek(0.0), SEEK_MIN_SECONDS);
        assert_eq!(clamp_seek(12.0), 12.0);
        assert_eq!(clamp_seek(10_000.0), SEEK_MAX_SECONDS);
        assert_eq!(clamp_seek(f64::NAN), SEEK_MIN_SECONDS);
    }
}
